<template>
  <view class="rpg-game">
    <view class="rpg-game__viewport" :style="stageCss">
    <image class="rpg-game__background" :src="assets.stadium" mode="aspectFill" />
    <view class="rpg-game__hud">
      <view class="rpg-game__side"><text>左腿</text><strong>{{ frame.left_count }}/{{ frame.target_count }}</strong><text>{{ frame.left_angle_deg.toFixed(0) }}°</text></view>
      <view class="rpg-game__center"><text>{{ targetText }} · 第{{ frame.set_index }}/{{ frame.target_sets }}组 · 得分 {{ game.score }} · 连击 ×{{ game.combo }}</text><view class="rpg-game__track"><view :style="progressStyle"/></view><text>{{ frame.overall_completion_percent }}%</text></view>
      <view class="rpg-game__side"><text>右腿</text><strong>{{ frame.right_count }}/{{ frame.target_count }}</strong><text>{{ frame.right_angle_deg.toFixed(0) }}°</text></view>
      <button class="rpg-game__pause" @click="togglePause">{{ guardState==='USER_PAUSED'?'▶':'Ⅱ' }}</button><button class="rpg-game__stop" @click="confirmStop">结束</button>
    </view>
    <view v-if="multiplayerSnapshot" class="rpg-game__multiplayer">
      <text>{{ multiplayerSnapshot.mode==='PK'?'实时排名':'团队进球' }}</text>
      <text v-if="multiplayerSnapshot.mode==='COOP'">{{ multiplayerSnapshot.teamContribution }}/{{ multiplayerSnapshot.teamTarget }}</text>
      <text v-else v-for="p in multiplayerSnapshot.players" :key="p.playerId">#{{ p.rank }} {{ p.displayName }} {{ p.score }}分</text>
    </view>
    <view class="rpg-game__goal"><view class="rpg-game__goal-frame"><view class="rpg-game__goal-net"></view></view><image class="rpg-game__keeper" :class="keeperClass" :src="keeperSrc" mode="aspectFit"/></view>
    <RpgPlayerRig class="rpg-game__player" :side="game.activeSide" :progress="activeProgress" :phase="game.phase" />
    <image class="rpg-game__ball" :class="ballClass" :src="assets.ball" mode="aspectFit"/>
    <image v-if="game.outcome" class="rpg-game__effect" :src="effectSrc" mode="aspectFit"/>
    <view class="rpg-game__feedback"><text>{{ game.feedback }}</text></view>
    <view v-if="overlayVisible" class="rpg-game__overlay"><view><text class="rpg-game__overlay-title">{{ overlayTitle }}</text><text>{{ overlayMessage }}</text><button v-if="guardState==='USER_PAUSED'" @click="togglePause">继续训练</button></view></view>
    <button v-if="config.debugEnabled" class="rpg-game__debug-toggle" @click="debugOpen=!debugOpen">{{ debugOpen?'收起调试':'展开调试' }}</button>
    <view v-if="config.debugEnabled&&debugOpen" class="rpg-game__debug"><RpgDebugControls @control="control" @cycle="cycle" @reset="reset"/></view>
    </view>
  </view>
</template>
<script lang="ts">
import RpgPlayerRig from '../components/PlayerRig.vue';import RpgDebugControls from '../components/DebugControls.vue'
import { PENALTY_ASSETS } from '../runtime/asset-paths';import { gameStageStyle,getViewportLayout } from '../../game-platform/runtime/viewport'
import { appendReturnUrl,configureCallerReturnUrl,returnToCaller } from '../../game-platform/runtime/navigation'
import { MotionSessionGuard,type SessionGuardState } from '../../game-platform/motion/session-guard'
import { indexedRandom } from '../../game-platform/random/seeded'
import { createPenaltyMotionDataSource } from '../data-sources/source-factory'
import { isAngleControllableSource,isSessionAwareSource,type HeldControl } from '../../game-platform/motion/data-source'
import { isCycleSimulatableSource } from '../data-sources/contracts';import { PenaltyKeyboardController } from '../data-sources/h5-keyboard-controller'
import { advancePenaltyPhase,applyPower,createInitialPenaltyState,createPenaltyResult,ShotEventReconciler,TrainingAccumulator,triggerShot,type PenaltyGameState } from '../core/game-engine'
import { KneeAngleInterpolator } from '../core/angle-interpolator'
import { createInitialKneeFrame,type ActiveSide,type KneeMotionFrame,type RepEvent } from '../types/motion'
import { getPenaltyConfig,publishPenaltyResult } from '../runtime/session-runtime'
import { getPenaltyMultiplayerClient,isPenaltyMultiplayer,leavePenaltyRoom,restorePenaltyMultiplayer,setPenaltyLocalResult } from '../runtime/multiplayer-runtime'
import type { RoomSnapshot } from '../../game-platform/multiplayer/types'

export default {
  name:'RpgGame',components:{RpgPlayerRig,RpgDebugControls},
  data(){const config=getPenaltyConfig();const frame=createInitialKneeFrame(config.targetCount,config.targetSets);return{assets:PENALTY_ASSETS,config,frame,visualLeft:0,visualRight:0,interpolator:new KneeAngleInterpolator(),game:createInitialPenaltyState() as PenaltyGameState,source:null as any,unsubscribe:null as (()=>void)|null,timer:null as ReturnType<typeof setInterval>|null,keyboard:null as PenaltyKeyboardController|null,guard:new MotionSessionGuard<KneeMotionFrame>({dataTimeoutMs:config.dataTimeoutMs,returnAngleDeg:config.returnAngleDeg}),guardState:'REARMING' as SessionGuardState,reconciler:new ShotEventReconciler(),accumulator:new TrainingAccumulator(),lastTick:Date.now(),viewport:getViewportLayout(),debugOpen:false,ending:false,pendingSides:[] as ActiveSide[],multiplayer:false,multiplayerSnapshot:null as RoomSnapshot|null,multiUnsubscribe:null as (()=>void)|null,shotSeed:0}},
  computed:{
    stageCss():Record<string,string>{return gameStageStyle(this.viewport,'--rpg-safe-top')},targetText():string{return`当前目标：${this.game.activeSide==='left'?'左腿':'右腿'}`},
    activeProgress():number{const angle=this.game.activeSide==='left'?this.visualLeft:this.visualRight;return Math.max(0,Math.min(1,angle/Math.max(1,this.frame.target_angle_deg)))},
    progressStyle():Record<string,string>{return{width:`${this.frame.overall_completion_percent}%`}},overlayVisible():boolean{return['USER_PAUSED','BACKGROUND_PAUSED','SOURCE_PAUSED','RESTING','DATA_INTERRUPTED'].includes(this.guardState)},
    overlayTitle():string{if(this.guardState==='RESTING')return`第 ${this.frame.set_index}/${this.frame.target_sets} 组完成`;if(this.guardState==='DATA_INTERRUPTED')return'动作数据中断';return'训练暂停'},
    overlayMessage():string{if(this.guardState==='RESTING')return`休息 ${this.frame.rest_remaining_sec} 秒，射门和计分已暂停`;if(this.guardState==='DATA_INTERRUPTED')return'请检查设备连接，恢复后先伸膝回位';return'继续后请先回到低角度伸膝位'},
    keeperSrc():string{if(this.game.phase!=='BALL_FLIGHT'&&this.game.phase!=='FEEDBACK')return this.assets.keeper.ready;if(this.game.outcome==='SAVE')return this.game.direction==='right'?this.assets.keeper.right:this.assets.keeper.left;return this.game.direction==='left'?this.assets.keeper.right:this.assets.keeper.left},
    keeperClass():string{return this.game.phase==='BALL_FLIGHT'||this.game.phase==='FEEDBACK'?`rpg-game__keeper--${this.game.direction}`:''},
    ballClass():string{return this.game.phase==='BALL_FLIGHT'||this.game.phase==='FEEDBACK'?`rpg-game__ball--fly rpg-game__ball--${this.game.direction} rpg-game__ball--${(this.game.outcome||'').toLowerCase()}`:''},
    effectSrc():string{return this.game.outcome==='GOAL'?this.assets.effects.goal:this.game.outcome==='SAVE'?this.assets.effects.save:this.assets.effects.miss}
  },
  onLoad(query:Record<string,string|undefined>){configureCallerReturnUrl(query?.returnUrl,'/pages-penalty-game/home/index');this.multiplayer=query?.multiplayer==='1';if(this.multiplayer&&!getPenaltyMultiplayerClient())restorePenaltyMultiplayer();if(this.multiplayer&&!isPenaltyMultiplayer()){this.ending=true;uni.showToast({title:'房间已退出',icon:'none'});setTimeout(()=>returnToCaller(),0);return}if(this.multiplayer){const client=getPenaltyMultiplayerClient();this.multiplayerSnapshot=client?.store.getSnapshot()??null;this.shotSeed=this.multiplayerSnapshot?.randomSeed??0;this.multiUnsubscribe=client?.store.subscribe((s)=>{this.multiplayerSnapshot=s})??null}this.start()},
  onResize(){this.viewport=getViewportLayout()},onHide(){if(this.ending)return;this.guard.pauseForBackground();this.sessionSource()?.setPaused(true);this.guardState=this.guard.getState()},onShow(){if(this.guardState==='BACKGROUND_PAUSED'){this.sessionSource()?.setPaused(false);this.guard.resume();this.guardState=this.guard.getState()}},
  onBackPress(){this.confirmStop();return true},onUnload(){this.cleanup();if(!this.ending)this.finish('STOPPED',false)},
  methods:{
    start(){this.source=createPenaltyMotionDataSource({targetCount:this.config.targetCount,targetSets:this.config.targetSets,frameRateHz:this.config.frameRateHz,targetAngleDeg:this.config.targetAngleDeg,validAngleDeg:this.config.validAngleDeg,returnAngleDeg:this.config.returnAngleDeg,restDurationSec:this.config.restDurationSec});this.unsubscribe=this.source.subscribe((f:KneeMotionFrame)=>this.onFrame(f));this.source.start();
      // #ifdef H5
      if(isAngleControllableSource<KneeMotionFrame>(this.source)){this.keyboard=new PenaltyKeyboardController(this.source,isCycleSimulatableSource(this.source)?this.source:null,this.config.debugEnabled,(c)=>this.devCommand(c));this.keyboard.attach()}
      // #endif
      this.lastTick=Date.now();this.timer=setInterval(()=>this.tick(),40)},
    onFrame(frame:KneeMotionFrame){if(this.ending)return;this.frame=frame;this.interpolator.update(frame);this.accumulator.accept(frame);this.guard.acceptFrame(frame);this.guardState=this.guard.getState();const reconciled=this.reconciler.accept(frame);if(reconciled.side){const event:RepEvent=reconciled.side==='left'?'left_rep_done':'right_rep_done';if(this.guard.canScore(event)){if(['KICKING','BALL_FLIGHT','FEEDBACK'].includes(this.game.phase))this.pendingSides.push(reconciled.side);else this.shoot(reconciled.side)}}
      if(frame.training_state==='FINISHED'||frame.training_state==='STOPPED'){this.finish(frame.training_state);return}this.sendProgress(frame)},
    shoot(side:ActiveSide){const index=this.game.shots;const outcome=()=>this.multiplayer?indexedRandom(this.shotSeed,index,0):Math.random();const direction=()=>this.multiplayer?indexedRandom(this.shotSeed,index,1):Math.random();this.game=triggerShot(this.game,side,outcome,direction).state},
    tick(){const now=Date.now();const delta=Math.min(200,Math.max(0,now-this.lastTick));this.lastTick=now;const visual=this.interpolator.sample(now);this.visualLeft=visual.left;this.visualRight=visual.right;if(this.guard.checkTimeout(now))this.guardState=this.guard.getState();if(['RUNNING','REARMING'].includes(this.guardState)){this.game=advancePenaltyPhase(this.game,delta);this.game=applyPower(this.game,this.activeProgress);if(this.game.phase==='WAITING_TARGET'&&this.pendingSides.length)this.shoot(this.pendingSides.shift() as ActiveSide)}},
    togglePause(){if(this.guardState==='USER_PAUSED'){this.sessionSource()?.setPaused(false);this.guard.resume()}else{this.guard.pauseByUser();this.sessionSource()?.setPaused(true)}this.guardState=this.guard.getState()},
    confirmStop(){if(this.ending)return;uni.showModal({title:'结束训练',content:'是否提前结束并保留本次训练数据？',success:(r)=>{if(r.confirm)this.finish('STOPPED')}})},
    finish(reason:'FINISHED'|'STOPPED',navigate=true){if(this.ending)return;this.ending=true;if(this.multiplayer)this.sendProgress({...this.frame,seq:this.frame.seq+1,training_state:reason,rep_event:'none'});this.guard.finish();const result=createPenaltyResult(reason,this.frame,this.game,this.guard.getTotalElapsedMs(),this.guard.getActiveElapsedMs(),this.accumulator.snapshot());publishPenaltyResult(result);if(this.multiplayer)setPenaltyLocalResult(result);this.cleanup();if(navigate){const url=this.multiplayer?'/pages-penalty-game/multiplayer/result/index':'/pages-penalty-game/result/index';uni.redirectTo({url:appendReturnUrl(url)})}else if(this.multiplayer)leavePenaltyRoom()},
    cleanup(){if(this.timer)clearInterval(this.timer);this.timer=null;this.keyboard?.detach();this.keyboard=null;this.unsubscribe?.();this.unsubscribe=null;this.multiUnsubscribe?.();this.multiUnsubscribe=null;this.source?.stop?.()},
    sessionSource(){return this.source&&isSessionAwareSource(this.source)?this.source:null},control(value:HeldControl,pressed:boolean){if(this.source&&isAngleControllableSource(this.source))this.source.setHeldControl(value,pressed)},cycle(side:ActiveSide){if(this.source&&isCycleSimulatableSource(this.source))this.source.simulateCompleteCycle(side)},reset(){this.source?.reset();this.reconciler.reset();this.game=createInitialPenaltyState()},
    devCommand(command:string){if(command==='pause')this.togglePause();else if(command==='reset')this.reset();else if(command==='finish'||command==='stop'){this.source?.finishTraining?.(command==='finish'?'FINISHED':'STOPPED')}} ,
    sendProgress(frame:KneeMotionFrame){if(!this.multiplayer)return;const client=getPenaltyMultiplayerClient();if(!client)return;client.sendProgress({motionSeq:frame.seq,repEvent:frame.rep_event,trainingState:frame.training_state,setIndex:frame.set_index,leftCount:frame.left_count,rightCount:frame.right_count,leftTotalCount:this.accumulator.snapshot().leftTotalCount,rightTotalCount:this.accumulator.snapshot().rightTotalCount,overallCompletionPercent:frame.overall_completion_percent,activeElapsedMs:this.guard.getActiveElapsedMs(),score:this.game.score,harvestedCount:this.game.goals,attempts:this.game.shots,successes:this.game.goals})}
  }
}
</script>
<style scoped>
.rpg-game{position:relative;display:flex;align-items:center;justify-content:center;width:100vw;height:100vh;height:100dvh;overflow:hidden;background:#183d2c;font-family:"Microsoft YaHei",sans-serif;color:#fff}.rpg-game__viewport{position:relative;flex:0 0 auto;width:1280px;height:720px;max-width:none;max-height:none;overflow:hidden;background:#55a84b}.rpg-game__background{position:absolute;inset:0;width:100%;height:100%}.rpg-game__hud{position:absolute;z-index:10;top:var(--rpg-safe-top,6px);left:var(--game-safe-left,12px);right:var(--game-safe-right,12px);display:flex;align-items:center;gap:8px;height:58px}.rpg-game__side{display:flex;align-items:center;justify-content:center;gap:8px;box-sizing:border-box;width:22vw;max-width:250px;height:54px;padding:0 10px;border:3px solid #1f69a4;border-radius:15px;background:rgba(250,253,255,.95);color:#205478;white-space:nowrap}.rpg-game__side strong{font-size:24px}.rpg-game__center{display:flex;flex:1;flex-direction:column;align-items:center;justify-content:center;min-width:0;text-shadow:0 2px 2px #174c77;font-weight:900}.rpg-game__center>text{font-size:13px;white-space:nowrap}.rpg-game__track{width:100%;height:12px;margin:2px;border:3px solid #174f7c;border-radius:10px;background:#133e60;overflow:hidden}.rpg-game__track view{height:100%;background:linear-gradient(90deg,#8ddd38,#42b827)}.rpg-game__pause,.rpg-game__stop{display:flex;align-items:center;justify-content:center;height:50px;margin:0;padding:0;border:3px solid #236ea7;line-height:1;font-weight:900}.rpg-game__pause{width:50px;border-radius:50%;background:#ffc328;color:#fff}.rpg-game__stop{width:68px;border-radius:13px;background:#f15b4d;color:#fff}.rpg-game__goal{position:absolute;z-index:3;top:18%;left:31%;width:38%;height:42%}.rpg-game__goal-frame{position:absolute;inset:0;box-sizing:border-box;border:7px solid rgba(255,255,255,.96);border-bottom-width:5px;border-radius:5px 5px 2px 2px;filter:drop-shadow(0 4px 4px rgba(21,70,91,.28))}.rpg-game__goal-net{position:absolute;inset:0;background-image:linear-gradient(rgba(255,255,255,.48) 2px,transparent 2px),linear-gradient(90deg,rgba(255,255,255,.48) 2px,transparent 2px);background-size:22px 22px}.rpg-game__keeper{position:absolute;z-index:2;left:35%;bottom:0;width:30%;height:75%;transition:transform 220ms}.rpg-game__keeper--left{transform:translateX(-75%) rotate(-22deg)}.rpg-game__keeper--right{transform:translateX(75%) rotate(22deg)}.rpg-game__keeper--center{transform:translateY(-4%)}.rpg-game__player{position:absolute;z-index:4;left:34.5%;bottom:-1%}.rpg-game__ball{position:absolute;z-index:6;left:49%;bottom:3%;width:62px;height:62px;transition:all 480ms ease-out}.rpg-game__ball--fly{bottom:51%;transform:scale(.48) rotate(560deg)}.rpg-game__ball--left{left:37%}.rpg-game__ball--right{left:62%}.rpg-game__ball--center{left:49%}.rpg-game__ball--miss.rpg-game__ball--left{left:22%}.rpg-game__ball--miss.rpg-game__ball--right{left:76%}.rpg-game__effect{position:absolute;z-index:8;top:28%;left:42%;width:16%;height:25%}.rpg-game__feedback{position:absolute;z-index:9;left:50%;bottom:2%;transform:translateX(-50%);padding:8px 22px;border-radius:999px;background:rgba(255,250,220,.95);color:#71430f;font-weight:900;white-space:nowrap}.rpg-game__multiplayer{position:absolute;z-index:11;top:calc(var(--rpg-safe-top,6px) + 65px);left:12px;display:flex;flex-direction:column;min-width:180px;padding:8px;border:2px solid #2a77ac;border-radius:12px;background:rgba(241,250,255,.94);color:#245b7e;font-size:11px}.rpg-game__overlay{position:absolute;z-index:30;inset:0;display:flex;align-items:center;justify-content:center;background:rgba(8,44,70,.58)}.rpg-game__overlay>view{width:72vw;max-width:480px;padding:24px;border:4px solid #3295d5;border-radius:22px;background:#fff;color:#31566f;text-align:center}.rpg-game__overlay text{display:block}.rpg-game__overlay-title{font-size:30px;font-weight:900}.rpg-game__overlay button{width:200px;margin-top:14px;border:0;border-radius:999px;background:#53bb2e;color:#fff}.rpg-game__debug-toggle{position:absolute;z-index:20;right:14px;bottom:8px;height:38px;margin:0;padding:0 14px;border:0;border-radius:12px;background:rgba(255,255,255,.9);color:#31556f}.rpg-game__debug{position:absolute;z-index:25;right:12px;bottom:52px}.rpg-game__effect{pointer-events:none}
.rpg-game__keeper{left:35%;z-index:2;transform-origin:50% 100%;transition:transform 220ms ease-out}
.rpg-game__keeper--left{transform:translateX(-52%) rotate(-22deg)}
.rpg-game__keeper--right{transform:translateX(62%) rotate(22deg)}

/* Shared 1280x720 stage overrides. */
.rpg-game__side { width: 280px; max-width: none; }
.rpg-game__overlay > view { width: 480px; max-width: 480px; }
</style>
